```json
{
  "root_causes": [
    {
      "service": "reservation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'abnormal' p, metric, service_name, count(*) n, min(value) mn, max(value) mx FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name='reservation' GROUP BY 1,2,3 UNION ALL SELECT 'normal', metric, service_name, count(*), min(value), max(value) FROM normal_metrics WHERE metric='k8s.deployment.available' AND service_name='reservation' GROUP BY 1,2,3",
          "claim": "Reservation deployment availability is 0 for all 13 abnormal samples, versus 1 in every normal sample."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' p, count(*) FILTER (WHERE service_name='reservation') reservation_spans, count(*) FILTER (WHERE service_name='frontend' AND span_name='reservation.Reservation/CheckAvailability' AND attr_status_code='Error') failed_checks FROM abnormal_traces UNION ALL SELECT 'normal', count(*) FILTER (WHERE service_name='reservation'), count(*) FILTER (WHERE service_name='frontend' AND span_name='reservation.Reservation/CheckAvailability' AND attr_status_code='Error') FROM normal_traces",
          "claim": "Reservation emits zero spans in the incident (2004 normally); 866 frontend CheckAvailability calls error out."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) c, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE span_name='reservation.Reservation/CheckAvailability' GROUP BY 1,2",
          "claim": "Frontend's CheckAvailability calls to reservation fail in about 0.016 ms, versus 0.69 ms normally, indicating no live backend."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) c FROM abnormal_logs WHERE message ILIKE 'Reservation check availability failed%' GROUP BY 1,2,3",
          "claim": "Frontend logs 768 'Reservation check availability failed' ERROR entries in the incident window."
        },
        {
          "kind": "metric",
          "sql": "SELECT time, metric, value, attr_k8s_pod_name FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name='reservation-57d77c7445-tkr7t' ORDER BY time",
          "claim": "Reservation pod tkr7t restart count climbs from 4 to 6 during the incident and its uptime series disappears."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "reservation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH hot AS (SELECT DISTINCT trace_id FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' AND attr_status_code='Error') SELECT t.service_name, t.span_name, t.attr_status_code, count(*) c, round(avg(t.duration)/1e6,2) ms FROM abnormal_traces t JOIN hot USING (trace_id) GROUP BY 1,2,3 ORDER BY c DESC",
          "claim": "Failed frontend HTTP /hotels traces (867) each contain a failed reservation CheckAvailability child, so the user-facing request fails."
        }
      ]
    }
  ]
}
